START TRANSACTION;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'descripcion', 'generic', '{"text": "Terralta A.C. celebra su V Torneo Anual de Invitación, edición 2026, del 26 de junio al 4 de julio de 2026 en las instalaciones del club.\\n\\nLa inscripción al Torneo Anual incluye: kit de bienvenida; Torneo de Putt Damas y Caballeros; Torneo de Approach Mixto; Torneo de Driver de Precisión Damas; Torneo de Driver de Distancia Caballeros; Torneo de Long Driver Caballeros; premios de O´yes; y alimentos y bebidas en los centros de consumo (jugador y cónyuge).\\n\\nPremio Hole In One: $1,000,000 al primer Hole In One en cualquiera de los 5 hoyos par 3. Si durante el torneo no se realiza ningún Hole In One, el premio se rifará entre los jugadores que hayan pagado su cuota de inscripción (la rifa se realiza el 4 de julio durante la Ceremonia de Premiación; es indispensable estar presente). Para un segundo o más Hole In One, el socio ganador recibirá un año de cuotas de mantenimiento sin costo; los no socios recibirán una membresía anual con cuota de mantenimiento incluida.\\n\\nDurante el desarrollo del Torneo queda restringido el acceso a menores de edad a la Casa Club, eventos sociales y premiación. Solo se autoriza el acceso a menores que jueguen en la categoría Premier de Caballeros y 1ª Categoría de Damas."}', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'generic',
  content = '{"text": "Terralta A.C. celebra su V Torneo Anual de Invitación, edición 2026, del 26 de junio al 4 de julio de 2026 en las instalaciones del club.\\n\\nLa inscripción al Torneo Anual incluye: kit de bienvenida; Torneo de Putt Damas y Caballeros; Torneo de Approach Mixto; Torneo de Driver de Precisión Damas; Torneo de Driver de Distancia Caballeros; Torneo de Long Driver Caballeros; premios de O´yes; y alimentos y bebidas en los centros de consumo (jugador y cónyuge).\\n\\nPremio Hole In One: $1,000,000 al primer Hole In One en cualquiera de los 5 hoyos par 3. Si durante el torneo no se realiza ningún Hole In One, el premio se rifará entre los jugadores que hayan pagado su cuota de inscripción (la rifa se realiza el 4 de julio durante la Ceremonia de Premiación; es indispensable estar presente). Para un segundo o más Hole In One, el socio ganador recibirá un año de cuotas de mantenimiento sin costo; los no socios recibirán una membresía anual con cuota de mantenimiento incluida.\\n\\nDurante el desarrollo del Torneo queda restringido el acceso a menores de edad a la Casa Club, eventos sociales y premiación. Solo se autoriza el acceso a menores que jueguen en la categoría Premier de Caballeros y 1ª Categoría de Damas."}',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'elegibilidad', 'generic', '{"eligibilityText": "Podrán participar damas y caballeros mayores de 18 años con estatus amateur que cuenten con hándicap GHIN vigente registrado en la FMG, publicado al 15 de mayo de 2026 (el más bajo si pertenecen a dos o más clubes).", "notesText": ["Categorías Campeonato y Premier (Caballeros): se permite participar a jugadores de 14 años en adelante con 0.0 de H.I., y deberán tener registros en torneos juveniles con scores por debajo de 85 golpes.", "Categorías Seniors: 50 a 60 años cumplidos al 15 de mayo de 2026. Super Seniors: 61 años o más cumplidos al 15 de mayo de 2026.", "1ª Categoría de Damas: se permite participar a jugadoras de 14 años en adelante con +5.0 a 14.8 de H.I., con registros en torneos juveniles con scores por debajo de 84 golpes.", "El Comité Organizador se reserva el derecho de aceptar a cualquier jugador o sembrarlo en otra categoría. Un jugador sin GHIN deberá firmar carta aceptando cualquier reclamación de otros jugadores y solo podrá participar por los premios de habilidades, O´yes, Hole In One y rifas, renunciando a la competencia principal.", "Hándicap: se jugará con el hándicap federado del 15 de mayo de 2026.", "Inscripciones para Socios: a partir del 16 de abril de 2026. Invitados: a partir del 1 de mayo de 2026. Cierre de inscripciones: 22 de junio de 2026.", "Brazalete: será indispensable el registro diario en la recepción del Club para contar con el brazalete de acceso al servicio de alimentos y bebidas. Debe portarse en la muñeca sin excepción."], "inscripcionesText": "Inscripciones: https://terralta.speitour.com (información del torneo, salidas, programa de juego y resultados).\\nInicio Socios: 16 de abril de 2026. Inicio Invitados: 1 de mayo de 2026. Cierre: 22 de junio de 2026."}', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'generic',
  content = '{"eligibilityText": "Podrán participar damas y caballeros mayores de 18 años con estatus amateur que cuenten con hándicap GHIN vigente registrado en la FMG, publicado al 15 de mayo de 2026 (el más bajo si pertenecen a dos o más clubes).", "notesText": ["Categorías Campeonato y Premier (Caballeros): se permite participar a jugadores de 14 años en adelante con 0.0 de H.I., y deberán tener registros en torneos juveniles con scores por debajo de 85 golpes.", "Categorías Seniors: 50 a 60 años cumplidos al 15 de mayo de 2026. Super Seniors: 61 años o más cumplidos al 15 de mayo de 2026.", "1ª Categoría de Damas: se permite participar a jugadoras de 14 años en adelante con +5.0 a 14.8 de H.I., con registros en torneos juveniles con scores por debajo de 84 golpes.", "El Comité Organizador se reserva el derecho de aceptar a cualquier jugador o sembrarlo en otra categoría. Un jugador sin GHIN deberá firmar carta aceptando cualquier reclamación de otros jugadores y solo podrá participar por los premios de habilidades, O´yes, Hole In One y rifas, renunciando a la competencia principal.", "Hándicap: se jugará con el hándicap federado del 15 de mayo de 2026.", "Inscripciones para Socios: a partir del 16 de abril de 2026. Invitados: a partir del 1 de mayo de 2026. Cierre de inscripciones: 22 de junio de 2026.", "Brazalete: será indispensable el registro diario en la recepción del Club para contar con el brazalete de acceso al servicio de alimentos y bebidas. Debe portarse en la muñeca sin excepción."], "inscripcionesText": "Inscripciones: https://terralta.speitour.com (información del torneo, salidas, programa de juego y resultados).\\nInicio Socios: 16 de abril de 2026. Inicio Invitados: 1 de mayo de 2026. Cierre: 22 de junio de 2026."}',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'costos', 'generic', '{"sociosPricing": [{"title": "Costo de Inscripción — Socios", "subtitle": "Cuotas aplicables únicamente para jugadores que participen en el Torneo.", "tiers": [{"categoria": "Caballeros Hijos", "costo": "$11,200.00"}, {"categoria": "Damas Hijas", "costo": "$5,800.00"}, {"categoria": "Socios Menores de 18 años", "costo": "$4,000.00"}]}], "foraneosPricing": [{"title": "Costo de Inscripción — Invitados", "subtitle": "Pago en una sola exhibición.", "tiers": [{"categoria": "Caballeros Invitados (incluye cónyuge en centros de consumo)", "costo": "$17,500.00"}, {"categoria": "Damas Invitadas (cónyuge no jugador con acceso a centros de consumo)", "costo": "$9,000.00"}, {"categoria": "Damas Invitadas (cónyuge juega el Torneo) — 50% aplicado", "costo": "$4,500.00"}, {"categoria": "Invitados Menores de 18 años", "costo": "$6,000.00"}, {"categoria": "Invitados Centros de Consumo (no jugadores) — por día", "costo": "$2,000.00"}, {"categoria": "Invitados Centros de Consumo (no jugadores) — toda la semana", "costo": "$8,000.00"}]}], "pricingNote": "Cargos de inscripción para Socios: si se inscriben en abril, el cargo se distribuye en 3 meses (abril, mayo y junio); en mayo, en 2 meses (mayo y junio); en junio, en 1 solo mes. Cónyuge jugadora aplica un 50% en su inscripción (Damas Invitadas) siempre y cuando ambos jueguen el torneo. Cancelaciones: no se aceptan bonificaciones por cancelación posterior al 25 de mayo; la cancelación deberá ser por https://terralta.speitour.com, sin excepción. La inscripción no es transferible.", "contactInfo": {"bankName": "Bancrea", "clabe": "152580120000725303", "cuenta": "12000072530", "nombre": "Terralta A.C.", "email": "", "telefono": "", "telefonoDirecto": ""}, "contactWarning": "Inscripciones e información completa en https://terralta.speitour.com", "inscripcionesText": "Inicio Socios: 16 de abril de 2026. Inicio Invitados: 1 de mayo de 2026. Cierre de inscripciones: 22 de junio de 2026."}', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'generic',
  content = '{"sociosPricing": [{"title": "Costo de Inscripción — Socios", "subtitle": "Cuotas aplicables únicamente para jugadores que participen en el Torneo.", "tiers": [{"categoria": "Caballeros Hijos", "costo": "$11,200.00"}, {"categoria": "Damas Hijas", "costo": "$5,800.00"}, {"categoria": "Socios Menores de 18 años", "costo": "$4,000.00"}]}], "foraneosPricing": [{"title": "Costo de Inscripción — Invitados", "subtitle": "Pago en una sola exhibición.", "tiers": [{"categoria": "Caballeros Invitados (incluye cónyuge en centros de consumo)", "costo": "$17,500.00"}, {"categoria": "Damas Invitadas (cónyuge no jugador con acceso a centros de consumo)", "costo": "$9,000.00"}, {"categoria": "Damas Invitadas (cónyuge juega el Torneo) — 50% aplicado", "costo": "$4,500.00"}, {"categoria": "Invitados Menores de 18 años", "costo": "$6,000.00"}, {"categoria": "Invitados Centros de Consumo (no jugadores) — por día", "costo": "$2,000.00"}, {"categoria": "Invitados Centros de Consumo (no jugadores) — toda la semana", "costo": "$8,000.00"}]}], "pricingNote": "Cargos de inscripción para Socios: si se inscriben en abril, el cargo se distribuye en 3 meses (abril, mayo y junio); en mayo, en 2 meses (mayo y junio); en junio, en 1 solo mes. Cónyuge jugadora aplica un 50% en su inscripción (Damas Invitadas) siempre y cuando ambos jueguen el torneo. Cancelaciones: no se aceptan bonificaciones por cancelación posterior al 25 de mayo; la cancelación deberá ser por https://terralta.speitour.com, sin excepción. La inscripción no es transferible.", "contactInfo": {"bankName": "Bancrea", "clabe": "152580120000725303", "cuenta": "12000072530", "nombre": "Terralta A.C.", "email": "", "telefono": "", "telefonoDirecto": ""}, "contactWarning": "Inscripciones e información completa en https://terralta.speitour.com", "inscripcionesText": "Inicio Socios: 16 de abril de 2026. Inicio Invitados: 1 de mayo de 2026. Cierre de inscripciones: 22 de junio de 2026."}',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

