INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (349, 'competencias', 'list', '{"items": [{"nombre": "Torneo de Driver de Distancia Caballeros", "descripcion": "Sistema: solo el primer golpe del Hoyo 1. Días: viernes 26 de junio al viernes 3 de julio (durante la ronda de juego). Categorías: Seniors, D, C, B, A y AA.", "premios": "Technogym Connected Dumbbells."}, {"nombre": "Torneo de Driver de Precisión Damas", "descripcion": "Sistema: solo el primer golpe del Hoyo 10 en los tres días de la competencia. Días: viernes 26, lunes 29 de junio y miércoles 1 de julio (durante la ronda de juego).", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Long Driver Caballeros", "descripcion": "Día: jueves 2 de julio, 17:00 a 19:30 hrs. Lugar: Terraza Bar ''La Vista''. Registro: mesa diaria de 14:00 a 18:00 hrs (no se puede participar dos veces ni repetir otro día). Calificarán a la final los mejores 52 lugares (42 caballeros y 10 damas) de los 7 días. Final: viernes 3 de julio, 20:30 hrs en Terraza Bar ''La Vista''. Cada participante tendrá 3 tiros y contará el tiro más cercano. El primer Hole In One será el mejor tiro. Empates: tiro adicional, gana quien la deje más cerca.", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Approach Mixto", "descripcion": "Calificación: viernes 26 de junio al jueves 2 de julio, 14:00 a 18:00 hrs en el Tee de Práctica. Cada jugador tendrá 3 oportunidades; califican los 7 mejores tiros del día. En total, calificarán 42 caballeros y 10 damas. Final: viernes 3 de julio, 20:30 hrs en Terraza Bar ''La Vista''. En caso de empates, gana el jugador que haya hecho el tiro primero.", "premios": "CFMoto CFORCE C5 al ganador del Torneo de Approach Mixto. 1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Putt Caballeros", "descripcion": "Calificación: viernes 26, sábado 27, domingo 28 de junio y jueves 2 de julio, 14:00 a 18:00 hrs en el Putting Green. Final: viernes 3 de julio, 18:00 hrs en el Putting Green.", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Putt Damas", "descripcion": "Día: lunes 29 de junio, 16:00 hrs en el Putting Green.", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Premios de O´yes", "descripcion": "Se premiarán los mejores O´yes diarios del Torneo en los hoyos 3, 5, 7, 12 y 16. También se premiará al mejor O´yes general de cada par 3 de todo el torneo. En caso de empate, gana quien hizo el tiro primero. Un jugador puede ganar dos o más O´yes con tiros diferentes.", "premios": "Premios por hoyo + premio especial al mejor O´yes general del Torneo (no aplica Hole In One)."}]}', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'list',
  content = '{"items": [{"nombre": "Torneo de Driver de Distancia Caballeros", "descripcion": "Sistema: solo el primer golpe del Hoyo 1. Días: viernes 26 de junio al viernes 3 de julio (durante la ronda de juego). Categorías: Seniors, D, C, B, A y AA.", "premios": "Technogym Connected Dumbbells."}, {"nombre": "Torneo de Driver de Precisión Damas", "descripcion": "Sistema: solo el primer golpe del Hoyo 10 en los tres días de la competencia. Días: viernes 26, lunes 29 de junio y miércoles 1 de julio (durante la ronda de juego).", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Long Driver Caballeros", "descripcion": "Día: jueves 2 de julio, 17:00 a 19:30 hrs. Lugar: Terraza Bar ''La Vista''. Registro: mesa diaria de 14:00 a 18:00 hrs (no se puede participar dos veces ni repetir otro día). Calificarán a la final los mejores 52 lugares (42 caballeros y 10 damas) de los 7 días. Final: viernes 3 de julio, 20:30 hrs en Terraza Bar ''La Vista''. Cada participante tendrá 3 tiros y contará el tiro más cercano. El primer Hole In One será el mejor tiro. Empates: tiro adicional, gana quien la deje más cerca.", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Approach Mixto", "descripcion": "Calificación: viernes 26 de junio al jueves 2 de julio, 14:00 a 18:00 hrs en el Tee de Práctica. Cada jugador tendrá 3 oportunidades; califican los 7 mejores tiros del día. En total, calificarán 42 caballeros y 10 damas. Final: viernes 3 de julio, 20:30 hrs en Terraza Bar ''La Vista''. En caso de empates, gana el jugador que haya hecho el tiro primero.", "premios": "CFMoto CFORCE C5 al ganador del Torneo de Approach Mixto. 1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Putt Caballeros", "descripcion": "Calificación: viernes 26, sábado 27, domingo 28 de junio y jueves 2 de julio, 14:00 a 18:00 hrs en el Putting Green. Final: viernes 3 de julio, 18:00 hrs en el Putting Green.", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Torneo de Putt Damas", "descripcion": "Día: lunes 29 de junio, 16:00 hrs en el Putting Green.", "premios": "1° $10,000 · 2° $6,000 · 3° $4,000 (Certificados Back 9)."}, {"nombre": "Premios de O´yes", "descripcion": "Se premiarán los mejores O´yes diarios del Torneo en los hoyos 3, 5, 7, 12 y 16. También se premiará al mejor O´yes general de cada par 3 de todo el torneo. En caso de empate, gana quien hizo el tiro primero. Un jugador puede ganar dos o más O´yes con tiros diferentes.", "premios": "Premios por hoyo + premio especial al mejor O´yes general del Torneo (no aplica Hole In One)."}]}',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

